rss.channel:

    {{- .Site.Title -}}


    {{- .Permalink -}}


    {{- .Site.Params.description | default .Site.Title -}}

Hugo -- gohugo.io
{{- with .Site.LanguageCode -}}

        {{- . -}}

{{- end -}}
{{- with .Site.Params.Author.email -}}

        {{- . }}{{ with $.Site.Params.Author.name }} ({{ . }}){{ end -}}


        {{- . }}{{ with $.Site.Params.Author.name }} ({{ . }}){{ end -}}

{{- end -}}
{{- with .Site.Copyright -}}

        {{- . -}}

{{- end -}}
{{- if not .Date.IsZero -}}

        {{- .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" -}}

{{- end -}}
{{ with .OutputFormats.Get "RSS" }}
    {{ printf "" .Permalink .MediaType | safeHTML }}
{{ end }}
{{- /* 订阅代表站点的全部公开更新：日常文章和结构化作品都应进入 Feed，
       否则 follow.it 邮件提醒会遗漏新案例。 */ -}}
{{- $subscribablePages := where .Site.RegularPages "Type" "in" (slice "posts" "works") -}}
{{- range $subscribablePages.ByDate.Reverse -}}
    {{- dict "Page" . "Site" .Site | partial "rss/item.html" -}}
{{- end -}}
